key:
mutating func append(_ x: Int) {
    if !isKnownUniquelyReferenced(&storage) {
        storage = Storage(storage.values)
    }
    storage.values.append(x)
}

isKnownUniquelyReferenced проверяет, что на объект ссылается только эта копия структуры. Если ссылок больше одной — сначала делаем свою копию, потом мутируем. Так копирование происходит только при записи в разделённое хранилище.

