final class FeedViewController: UIViewController {
    override func viewDidLoad() {
        super.viewDidLoad()
        NotificationCenter.default.addObserver(
            forName: .didLogout, object: nil, queue: .main
        ) { _ in
            self.reload()
        }
    }
    func reload() { }
    deinit { print("deinit") }
}

key:
Блочный addObserver возвращает токен, а NotificationCenter сильно держит блок до removeObserver(token). Блок сильно захватывает self — контроллер живёт вечно.
Починка: [weak self] в блоке и сохранить токен, чтобы снять наблюдение:
private var token: NSObjectProtocol?
token = NotificationCenter.default.addObserver(forName: .didLogout, object: nil, queue: .main) { [weak self] _ in self?.reload() }
deinit { if let token { NotificationCenter.default.removeObserver(token) } }

