key:
func loadAll(_ urls: [URL], completion: @escaping ([Data]) -> Void) {
    let group = DispatchGroup()
    let lock = NSLock()
    var results: [Data] = []
    for url in urls {
        group.enter()
        URLSession.shared.dataTask(with: url) { data, _, _ in
            defer { group.leave() }
            guard let data else { return }
            lock.lock(); results.append(data); lock.unlock()
        }.resume()
    }
    group.notify(queue: .main) { completion(results) }
}

enter перед запуском, leave в defer — на любом пути. Колбэки приходят на разных потоках, поэтому append под замком. Порядок результатов не гарантирован.

