let semaphore = DispatchSemaphore(value: 2)
for url in urls {
    queue.async {
        semaphore.wait()
        defer { semaphore.signal() }
        download(url)
    }
}

value: 2 — два свободных слота. wait уменьшает счётчик и блокирует поток при нуле; signal возвращает слот. Никогда не вызывай wait на главном потоке — заморозишь UI.

