final class SafeCache {
    private var dict: [String: Data] = [:]
    private let queue = DispatchQueue(label: "cache", attributes: .concurrent)

    func get(_ key: String) -> Data? {
        // ?
    }
    func set(_ key: String, _ value: Data) {
        // ?
    }
}

key:
func get(_ key: String) -> Data? {
    queue.sync { dict[key] }
}
func set(_ key: String, _ value: Data) {
    queue.async(flags: .barrier) { self.dict[key] = value }
}

На concurrent-очереди обычные sync-чтения идут параллельно. Барьерный блок ждёт, пока закончатся все начатые задачи, выполняется один, и только потом очередь продолжает. Важно: barrier работает только на своей concurrent-очереди, не на global().

